import{z as A,x as C,o as E,c as B,q as o,j as n,D as r,d as s,s as t,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Las Vegas 与 Monte Carlo","description":"","frontmatter":{"title":"Las Vegas 与 Monte Carlo","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/las-vegas-monte-carlo.md","filePath":"cs/las-vegas-monte-carlo.md","lastUpdated":1791413859000}'),d={name:"cs/las-vegas-monte-carlo.md"};function p(m,a,g,h,V,c){const l=C("Mermaid");return E(),B("div",null,[a[2]||(a[2]=o('<h1 id="las-vegas-与-monte-carlo" tabindex="-1">Las Vegas 与 Monte Carlo <a class="header-anchor" href="#las-vegas-与-monte-carlo" aria-label="Permalink to &quot;Las Vegas 与 Monte Carlo&quot;">​</a></h1><div class="epigraph"><p>Las Vegas 永远正确、时间随机；Monte Carlo 限时、以小概率错。重复与双边错误把 RP/BPP 与期望多项式分开。</p><footer>—— 据 Motwani and Raghavan, Randomized Algorithms, 1995；[随机化算法直觉](/cs/randomized-algo)；CLRS 第 5 章整理</footer></div><p>上一课<a href="/cs/karger-min-cut">Karger 最小割</a>是典型 Monte Carlo：可能报更大的割。主干已分两类。本课缺口是<strong>钉术语</strong>并接上 Karger、rho、指纹：何时可变成 Las Vegas（有验证器）。不重写指示器。后课 Freivalds 指纹。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Las Vegas：输出正确，如随机快排、随机增量几何（期望 \\(O(n\\log n)\\)）。可中止重来，期望时间有界。Monte Carlo：Karger、Miller–Rabin（单侧）、指纹相等（碰撞则可能错）。单侧错误可重复压概率。有确定性多项式验证（NP 证书或最小割再检查）则 MC 可改 LV：错就重抽，直到验证过。</p><p><span class="marginnote">术语翻译：单侧错误就是「只会错一边」。Miller–Rabin 说「这是合数」时给出的是铁证、绝不会错；只有说「这是素数」时才可能看走眼。所以错了的那一侧可以靠重复运行把概率指数压小；双侧错误（BPP）两边都可能错，就得靠多数投票。</span></p><p>缺口是分类，不是新算法。</p><h3 id="期望多项式不是最坏多项式" tabindex="-1">期望多项式不是最坏多项式 <a class="header-anchor" href="#期望多项式不是最坏多项式" aria-label="Permalink to &quot;期望多项式不是最坏多项式&quot;">​</a></h3><p>LV 最坏可很长。MC 最坏时间固定。不要把「平均输入」与「算法内硬币」混。</p><p><span class="marginnote">常见误区：初学者容易把 LV 的「期望时间」当成「输入平均不坏」。实际上硬币是算法自己掷的：随机快排对任何一个固定输入——包括最坏的已排序数组——期望运行时间都是 \\(O(n \\log n)\\)，期望是对算法的随机性取的，与输入分布无关。</span></p><p><span class="marginnote">Motwani–Raghavan。RP：单侧错；BPP 双侧。本课算法，复杂度类点名。后课 Freivalds 是 MC 矩阵乘检验。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写算法时声明：错从哪来、能否验证、重复几次。Karger：可用流验证全局割是否等于报的值（对无向）。指纹：碰撞无法本地验证相等。</p>',13)),(E(),n(i,null,{default:r(()=>[t(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20LV%5B%22%E6%B0%B8%E8%BF%9C%E5%AF%B9%EF%BC%8C%E6%97%B6%E9%97%B4%E9%9A%8F%E6%9C%BA%22%5D%20--%3E%20EX%5B%22%E6%9C%9F%E6%9C%9B%E5%A4%9A%E9%A1%B9%E5%BC%8F%22%5D%0A%20%20MC%5B%22%E9%99%90%E6%97%B6%EF%BC%8C%E5%8F%AF%E9%94%99%22%5D%20--%3E%20REP%5B%22%E9%87%8D%E5%A4%8D%E5%8E%8B%E5%A4%B1%E8%B4%A5%E6%A6%82%E7%8E%87%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"错误概率对最坏输入取，不是平均实例。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"重复 \\(k\\) 次独立，失败 \\((1-p)^k\\)。双侧错误要 Chernoff 或多数票。与近似比：随机近似给期望比或高概率比，后课。与在线：在线没有「重复整个输入」。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"数字实例：单次错误概率 \\(p=\\frac{1}{3}\\) 时，重复 10 次独立运行、全错的概率只有 \\((\\frac{1}{3})^{10} \\approx 1.7\\times 10^{-5}\\)；重复 20 次就降到 \\(3\\times 10^{-10}\\)。每多跑一次几乎白拿一个数量级——这是随机算法最划算的地方。")],-1)),a[7]||(a[7]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：MC 改 LV 的条件可以想象成「对答案」。考试时先蒙一个答案（MC 运行），如果后面有标准答案可查（验证器），蒙错了就重蒙，最终交卷的一定对（LV）；如果没法对答案（指纹相等没有本地验证），就只能多蒙几遍靠概率压错误。")],-1)),(E(),n(i,null,{default:r(()=>[t(l,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E8%BF%90%E8%A1%8C%E4%B8%80%E6%AC%A1%20MC%20%E7%AE%97%E6%B3%95%22%5D%20--%3E%20V%7B%22%E6%9C%89%E6%B2%A1%E6%9C%89%E6%9C%AC%E5%9C%B0%E9%AA%8C%E8%AF%81%E5%99%A8%3F%22%7D%0A%20%20V%20--%3E%7C%22%E6%9C%89%3A%20%E5%A6%82%E5%89%B2%E5%80%BC%E5%8F%AF%E7%94%A8%E6%B5%81%E5%A4%8D%E7%AE%97%22%7C%20C%7B%22%E9%AA%8C%E8%AF%81%E9%80%9A%E8%BF%87%3F%22%7D%0A%20%20C%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20OUT%5B%22%E8%BE%93%E5%87%BA%3A%20%E5%BF%85%E6%AD%A3%E7%A1%AE%2C%20%E5%B7%B2%E6%98%AF%20LV%22%5D%0A%20%20C%20--%3E%7C%22%E5%A4%B1%E8%B4%A5%22%7C%20R%5B%22%E9%87%8D%E6%8A%BD%E7%A1%AC%E5%B8%81%2C%20%E5%86%8D%E8%B7%91%E4%B8%80%E6%AC%A1%22%5D%0A%20%20R%20--%3E%20S%0A%20%20V%20--%3E%7C%22%E6%B2%A1%E6%9C%89%3A%20%E5%A6%82%E6%8C%87%E7%BA%B9%E7%9B%B8%E7%AD%89%22%7C%20ERR%5B%22%E6%97%A0%E6%B3%95%E6%9C%AC%E5%9C%B0%E7%BA%A0%E9%94%99%2C%20%E5%8F%AA%E8%83%BD%E9%87%8D%E5%A4%8D%E5%8E%8B%E6%A6%82%E7%8E%87%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<p>这张图回答的问题：MC 何时能改写成 LV。关键分叉是「有无本地验证器」——有则失败重抽的循环把错误彻底清零（只花时间不冒错），没有则只能靠独立重复把失败概率从 \\(p\\) 压到 \\((1-p)^k\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 \\(P=BPP?\\)。不写全部 RP 完全问题。后课默认：先分 LV/MC 再分析。下一课指纹与 Freivalds。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LV 正确；MC 可错可限时。</li><li>有验证器则 MC 可改 LV。</li><li>Karger 是 MC；快排是 LV。</li><li>出处：Motwani and Raghavan, 1995；CLRS。</li></ul>',5))])}const D=A(d,[["render",p]]);export{f as __pageData,D as default};
